struct above { int threshold; };                     /* the bound arguments */

static int cmp_above(const void *a, const void *b, void *ctx)
{
    const struct above *bound = ctx;                 /* recover the binding */
    return (*(const int *)a > bound->threshold)
         - (*(const int *)b > bound->threshold);
}

struct above bound = { .threshold = 10 };
qsort_r(values, n, sizeof *values, cmp_above, &bound);
